async function withRetry(fn, { max = 5, base = 200 } = {}) {
  for (let i = 0; i < max; i++) {
    try { return await fn(); }
    catch (e) {
      if (i === max - 1) throw e;
      await new Promise(r => setTimeout(r, base * 2 ** i));
    }
  }
}

