const jwt = require("jsonwebtoken");
const SECRET = process.env.JWT_SECRET;

function sign(payload, ttl = "1h") {
  return jwt.sign(payload, SECRET, { expiresIn: ttl });
}
function auth(req, res, next) {
  const h = req.headers.authorization || "";
  const token = h.startsWith("Bearer ") ? h.slice(7) : null;
  if (!token) return res.status(401).json({ error: "missing token" });
  try { req.user = jwt.verify(token, SECRET); next(); }
  catch { res.status(401).json({ error: "invalid token" }); }
}
module.exports = { sign, auth };

const redis = require("redis").createClient();
redis.connect();
const cache = {
  get: (k) => redis.get(k),
  set: (k, v, ttl = 60) => redis.set(k, JSON.stringify(v), "EX", ttl),
  getOrSet: async (k, loader, ttl) => {
    const hit = await redis.get(k);
    if (hit) return JSON.parse(hit);
    const v = await loader();
    await cache.set(k, v, ttl);
    return v;
  },
  del: (k) => redis.del(k),
};

const queue = [];
let running = 0, max = 3;
function enqueue(task) { queue.push(task); pump(); }
function pump() {
  if (running < max && queue.length) {
    const task = queue.shift();
    running++;
    task().catch((e) => { console.error(e); enqueue(task); }).finally(() => running-- && pump());
  }
}
module.exports = { enqueue };

function paginate(page, size, total) {
  const cur = Math.max(1, Number(page) || 1);
  const lim = Math.max(1, Math.min(100, Number(size) || 20));
  const pages = Math.ceil(total / lim);
  return { page: cur, size: lim, total, pages, offset: (cur - 1) * lim };
}
