function makeFsm(initial, transitions) {
  let state = initial;
  return {
    current: () => state,
    send: (ev) => {
      const next = transitions[state] && transitions[state][ev];
      if (!next) throw new Error("no transition " + ev + " from " + state);
      state = next;
