function levelOrder(root) {
  if (!root) return [];
  const q = [root], out = [];
  while (q.length) { const n = q.length; for (let i = 0; i < n; i++) { const c = q.shift(); out.push(c.val); c.left && q.push(c.left); c.right && q.push(c.right); } }
  return out;
}

