class DSU {
  constructor(n) { this.p = [...Array(n).keys()]; this.r = new Array(n).fill(1); }
  find(x) { while (this.p[x] !== x) { this.p[x] = this.p[this.p[x]]; x = this.p[x]; } return x; }
  union(a, b) { const ra = this.find(a), rb = this.find(b); if (ra === rb) return false; if (this.r[ra] < this.r[rb]) [ra, rb] = [rb, ra]; this.p[rb] = ra; this.r[ra] += this.r[rb]; return true; } }

function bfs(start) {
  const q = [start], seen = new Set([start]);
  while (q.length) {
    const u = q.shift();
    for (const v of neighbors(u)) if (!seen.has(v)) { seen.add(v); q.push(v); }
  }
}
function dfs(u, seen = new Set()) {
  seen.add(u);
  for (const v of neighbors(u)) if (!seen.has(v)) dfs(v, seen);
}

function quick(arr) {
  if (arr.length < 2) return arr;
  const [p, ...r] = arr;
  return [...quick(r.filter(x => x < p)), p, ...quick(r.filter(x => x >= p))];
}
function merge(arr) {
  if (arr.length < 2) return arr;
  const m = arr.length >> 1, L = merge(arr.slice(0, m)), R = merge(arr.slice(m));
  const out = [];
  while (L.length && R.length) out.push(L[0] < R[0] ? L.shift() : R.shift());
  return out.concat(L, R);
}
